(function(root){
const amount=v=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))?Number(v):null;
function math(l,percent=l.percent??70,repair=l.repairBase??l.repairs){const arv=amount(l.arv),repairs=amount(repair),costs=amount(l.costs)??0,seller=amount(l.sellerTarget);if(arv===null||arv<=0||repairs===null)return null;const max=arv*percent/100-repairs-costs;return {max,ceiling:max-(amount(l.fee)??10000),gross:seller===null?null:max-seller,net:seller===null?null:max-seller-(amount(l.assignmentCosts)??0),buyerAsk:seller===null?null:seller+(amount(l.fee)??10000)};}
const distance=(a,b)=>{const r=v=>v*Math.PI/180,h=Math.sin(r(b.latitude-a.latitude)/2)**2+Math.cos(r(a.latitude))*Math.cos(r(b.latitude))*Math.sin(r(b.longitude-a.longitude)/2)**2;return 3958.8*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))};
function matches(i,l){const sameCounty=l.county&&(i.counties||[]).some(c=>c.toLowerCase()===l.county.toLowerCase()),sameCity=(i.markets||[i.city||'']).some(c=>c.toLowerCase()===String(l.city||'').toLowerCase());if(!sameCounty&&!sameCity)return {level:0,label:'Market not confirmed'};const m=math(l);if(i.budget&&m&&m.max>i.budget)return {level:0,label:'Exceeds saved budget'};if(i.maxRepairs&&amount(l.repairHigh)!==null&&l.repairHigh>i.maxRepairs)return {level:0,label:'Exceeds repair limit'};return {level:i.buyBoxConfirmed&&m&&i.budget?2:1,label:i.buyBoxConfirmed&&m&&i.budget?'Saved budget fits · verify property criteria':'Market match · buy box unconfirmed'};}
function safeDeal(l){const m=math(l);return {address:l.address,city:l.city,state:l.state||'TN',zip:l.zip,county:l.county,propertyType:l.propertyType||'Unconfirmed',beds:l.beds??null,baths:l.baths??null,sqft:l.sqft??null,arv:amount(l.arv),repairLow:amount(l.repairLow),repairBase:amount(l.repairBase??l.repairs),repairHigh:amount(l.repairHigh),buyerAsk:m?.buyerAsk??null,maxBuy:m?.max??null,equitableInterest:!!l.equitableInterest,publicCondition:l.publicCondition||'Condition not inspected',comps:(l.comps||[]).slice(0,3).map(c=>({address:c.address,price:c.price,sqft:c.sqft,date:c.date,source:c.source})),dataMode:l.dataMode||'Manual',valuationVerified:!!l.valuationVerified};}
const fmt=v=>amount(v)===null?'not yet estimated':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
function investorDraft(l,i,sender,channel){const d=safeDeal(l),opening=d.equitableInterest?'I have a potential assignment opportunity':'I’m researching a property and checking buyer interest; I do not yet hold an assignable contract';const facts=`${d.address}, ${d.city||d.county||'Tennessee'}. ${d.sqft?d.sqft+' sq ft; ':''}ARV ${fmt(d.arv)}; repairs ${fmt(d.repairBase)}${d.buyerAsk!==null?'; proposed buyer price '+fmt(d.buyerAsk):''}. Estimates are preliminary.`;const body=`Hi ${i?.name||'there'}, this is ${sender||'[your name]'}. ${opening}: ${facts} Does this fit your current buy box? What purchase price and closing timeline would work for you? ${channel==='email'?'I can provide a property-only Deal Sheet. ':''}If you prefer no further messages, let me know.`;return {subject:`Property review: ${d.address}`,body};}
function sellerDraft(l,sender,role){return `Hello, I’m ${sender||'[your name]'}${role?', '+role:''}. I’m interested in the property at ${l.address}. Are you the right person to speak with about a possible sale? If you would consider selling, I’d like to learn about the property and discuss a written offer${amount(l.sellerTarget)!==null?' around '+fmt(l.sellerTarget)+', subject to inspection and due diligence':''}. There is no obligation. If you prefer no further contact, please let me know and I’ll update my records.`;}
function blocked(c){return !!(c?.dnc||c?.optout)}
const api={math,distance,matches,safeDeal,investorDraft,sellerDraft,blocked,amount,fmt};if(typeof module!=='undefined')module.exports=api;else root.DealCore=api;
})(globalThis);
